data: {"index":1,"delta":{"text":") directly seek out and destroy cells that have been infected.\n\n#### The Ultimate Goal: Immunological Memory\n\nThe most","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" critical outcome of vaccination is the creation of **immunological memory**. After the \"training exercise\" is complete and the vaccine","type":"text"},"event_type":"step.delta"}

